class ILogger {
  log(_msg) { throw new Error('ILogger.log must be implemented'); }
  error(_msg) { throw new Error('ILogger.error must be implemented'); }
  warn(_msg) { throw new Error('ILogger.warn must be implemented'); }
  setLevel(_level) { throw new Error('ILogger.setLevel must be implemented'); }
}

module.exports = { ILogger };

const { ILogger } = require('./ilogger');

class Logger extends ILogger {
  constructor(level = 'info') {
    super();
    this.level = level;
  }

  log(msg) { if (this.level !== 'silent') console.log('[LOG]', msg); }
  error(msg) { console.error('[ERR]', msg); }
  warn(msg) { if (this.level !== 'silent') console.warn('[WARN]', msg); }
  setLevel(level) { this.level = level; }
}

module.exports = { Logger };

const { Logger } = require('./logger');

/** @typedef {import('./ilogger').ILogger} ILogger */

const defaultLogger = new Logger('info');

/** @param {ILogger} [log] */
function run(log = defaultLogger) {
  log.log('App started');
  log.warn('Config missing');
  log.error('DB connection failed');
}

module.exports = { run };

const { Logger } = require('./logger');

/** @typedef {import('./ilogger').ILogger} ILogger */

const defaultLogger = new Logger('silent');

/** @param {ILogger} [log] */
function process(log = defaultLogger) {
  log.log('Worker processing');
  log.error('Queue full');
}

module.exports = { process };

const { ILogger } = require('../src/ilogger');
const { Logger } = require('../src/logger');
const assert = require('assert');

describe('Logger', () => {
  it('should implement ILogger', () => {
    assert.ok(new Logger() instanceof ILogger);
  });

  it('should create logger with default level', () => {
    const l = new Logger();
    assert.equal(l.level, 'info');
  });

  it('should support silent level', () => {
    const l = new Logger('silent');
    assert.equal(l.level, 'silent');
  });
});

